import{_ as l,C as r,o as n,c as s,j as t,a as d,E as o,a5 as c}from"./chunks/framework.CINlqUGR.js";const P=JSON.parse('{"title":"面包屑","description":"","frontmatter":{},"headers":[],"relativePath":"components/breadcrumb.md","filePath":"components/breadcrumb.md","lastUpdated":1787359578000}'),h={name:"components/breadcrumb.md"},b={id:"面包屑",tabindex:"-1"};function u(p,e,m,x,f,q){const i=r("Badge"),a=r("XhDemo");return n(),s("div",null,[t("h1",b,[e[0]||(e[0]=d("面包屑 ",-1)),o(i,{type:"info",text:"breadcrumb"}),e[1]||(e[1]=d()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#面包屑","aria-label":'Permalink to "面包屑 <Badge type="info" text="breadcrumb" />"'},"​",-1))]),e[3]||(e[3]=c('<p>把当前位置在层级里的路径摊开，每一层都能点回去。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>层级超过两级且用户可能从搜索或外链直接进到深层。</li><li>需要让用户知道&quot;我在哪，上一层是什么&quot;。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>站点是扁平的：路径只有一层，写它没有信息量。</li><li>用来表达步骤的先后：那是<a href="./steps">步骤条</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>href</code> 归作者写；末级只多一个 <code>current</code>：它拿到 <code>aria-current=&quot;page&quot;</code>、点不动、也不占 Tab 位。</li><li>中间层级可以折叠成省略号；省略号与分隔符都对读屏隐藏，念出来仍是完整的列表项数。</li><li><code>root</code> 是 <code>nav</code> 地标，<code>translations.root</code> 换掉它的 <code>aria-label</code>。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>href 归作者写，末级只多一个 current：它拿到 aria-current=&quot;page&quot;、点不动、也不占 Tab 位</p>',10)),o(a,{src:"breadcrumb/01-basic"}),e[4]||(e[4]=t("h3",{id:"折叠中间层级",tabindex:"-1"},[d("折叠中间层级 "),t("a",{class:"header-anchor",href:"#折叠中间层级","aria-label":'Permalink to "折叠中间层级"'},"​")],-1)),e[5]||(e[5]=t("p",null,"省略号与分隔符同为 ol 的直接子 li，两者都对读屏隐藏，念出来仍是「列表，共 3 项」",-1)),o(a,{src:"breadcrumb/02-ellipsis"}),e[6]||(e[6]=t("h3",{id:"读屏文案",tabindex:"-1"},[d("读屏文案 "),t("a",{class:"header-anchor",href:"#读屏文案","aria-label":'Permalink to "读屏文案"'},"​")],-1)),e[7]||(e[7]=t("p",null,"root 是 nav 地标，translations.root 换掉它的 aria-label，同页有多个地标时靠它区分",-1)),o(a,{src:"breadcrumb/03-translations"}),e[8]||(e[8]=t("h3",{id:"语气",tabindex:"-1"},[d("语气 "),t("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),e[9]||(e[9]=t("p",null,"tone 换的是当前项的文字色，以及可点那几层悬停时的文字色；末级预置为当前项",-1)),o(a,{src:"breadcrumb/04-tone"}),e[10]||(e[10]=t("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),e[11]||(e[11]=t("p",null,"size 换整条路径的字号与各层之间的间距，不传 size 即默认档",-1)),o(a,{src:"breadcrumb/05-size"}),e[12]||(e[12]=t("h3",{id:"层级下拉",tabindex:"-1"},[d("层级下拉 "),t("a",{class:"header-anchor",href:"#层级下拉","aria-label":'Permalink to "层级下拉"'},"​")],-1)),e[13]||(e[13]=t("p",null,"某一层要换去处时，把菜单整套放进 item 里；面包屑只管这一层的排版",-1)),o(a,{src:"breadcrumb/06-dropdown"}),e[14]||(e[14]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-breadcrumb&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhBreadcrumbEllipsis</code> <code>XhBreadcrumbItem</code> <code>XhBreadcrumbLink</code> <code>XhBreadcrumbList</code> <code>XhBreadcrumbRoot</code> <code>XhBreadcrumbSeparator</code></td></tr><tr><td>组合式函数</td><td><code>useBreadcrumb</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/breadcrumb.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;breadcrumb&quot;</code>：<strong><code>root</code></strong> · <strong><code>list</code></strong> · <strong><code>item</code></strong> · <strong><code>link</code></strong> · <code>separator</code> · <code>ellipsis</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，只作用于排版；作者没给就不写。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;BreadcrumbTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useBreadcrumb</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLinkProps</code></td><td><code>(props: BreadcrumbLinkProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getEllipsisProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/breadcrumb/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>focus in link, 非当前页</td><td>跟随链接（原生 &lt;a href&gt; 的激活行为，面包屑自己不监听按键）</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus in root</td><td>逐条走过可点的链接；面包屑不做 roving tabindex，当前页那条带 tabindex=-1 自动脱序</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.translations?.root</td></tr><tr><td><code>link</code></td><td><code>aria-current</code></td><td>&#39;page&#39; | undefined</td></tr><tr><td><code>link</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>ellipsis</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/breadcrumb.css</code> 按部件选择：<code>[data-scope=&quot;breadcrumb&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>link</code></td><td><code>data-current</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-breadcrumb-current-fg</code> · <code>--xh-breadcrumb-current-font-weight</code> · <code>--xh-breadcrumb-ellipsis-size</code> · <code>--xh-breadcrumb-fg</code> · <code>--xh-breadcrumb-font-size</code> · <code>--xh-breadcrumb-gap</code> · <code>--xh-breadcrumb-icon-size</code> · <code>--xh-breadcrumb-leading</code> · <code>--xh-breadcrumb-link-bg-hover</code> · <code>--xh-breadcrumb-link-fg-hover</code> · <code>--xh-breadcrumb-link-gap</code> · <code>--xh-breadcrumb-link-max-w</code> · <code>--xh-breadcrumb-link-px</code> · <code>--xh-breadcrumb-link-radius</code> · <code>--xh-breadcrumb-separator-fg</code> · <code>--xh-breadcrumb-separator-size</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>放进<a href="./page-header">页头</a>；某一层要换去处时把整套<a href="./menu">菜单</a>放进那一项里。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>末级写当前页标题，别写&quot;详情&quot;这种没有信息的词。</li><li>同页有多个 <code>nav</code> 地标时给面包屑单独的 <code>aria-label</code>。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿面包屑记录浏览历史：它表达的是层级位置，不是来路。</li><li>末级也做成链接指向自己。</li></ul>',35))])}const k=l(h,[["render",u]]);export{P as __pageData,k as default};
